package pl.zagranietyper.service;
import pl.zagranietyper.model.*;import pl.zagranietyper.parser.FootballTeamFirstGoalSyntaxAdapter;import pl.zagranietyper.repository.FootballFixtureEventsRepository;import java.util.*;

/** Pure settlement over a COMPLETE canonical event timeline and known final score. */
public final class FootballTeamFirstGoalSettlementEngine {
 public Result settle(FootballTeamFirstGoalSyntaxAdapter.Side selected,FootballScore ft,FootballFixtureEventsRepository.FixtureTimeline timeline){if(selected==null||ft==null||timeline==null||timeline.status()!=FootballFixtureEventsSnapshot.FetchStatus.COMPLETE||timeline.homeTeamId()==null||timeline.awayTeamId()==null)return unsupported(Reason.MISSING_DATA);List<FootballFixtureEventsSnapshot.Event>goals=new ArrayList<>();for(var e:timeline.events()){if(!"goal".equalsIgnoreCase(e.type())||"missed penalty".equalsIgnoreCase(e.detail()))continue;if(e.minute()==null||e.teamId()==null||(!e.teamId().equals(timeline.homeTeamId())&&!e.teamId().equals(timeline.awayTeamId())))return unsupported(Reason.AMBIGUOUS_CHRONOLOGY);goals.add(e);}long home=goals.stream().filter(e->e.teamId().equals(timeline.homeTeamId())).count(),away=goals.stream().filter(e->e.teamId().equals(timeline.awayTeamId())).count();if(home!=ft.home()||away!=ft.away())return unsupported(Reason.SCORE_INCONSISTENT);if(goals.isEmpty())return unsupported(Reason.NO_GOALS);goals.sort(Comparator.comparingInt(FootballFixtureEventsSnapshot.Event::minute).thenComparingInt(e->e.extraMinute()==null?0:e.extraMinute()).thenComparingInt(FootballFixtureEventsSnapshot.Event::sourceIndex));var first=goals.getFirst();var actual=first.teamId().equals(timeline.homeTeamId())?FootballTeamFirstGoalSyntaxAdapter.Side.HOME:FootballTeamFirstGoalSyntaxAdapter.Side.AWAY;return new Result(actual==selected?SettlementDecision.W:SettlementDecision.L,Reason.SETTLED,first);}
 private static Result unsupported(Reason r){return new Result(SettlementDecision.UNSUPPORTED,r,null);}public enum Reason{SETTLED,MISSING_DATA,SCORE_INCONSISTENT,NO_GOALS,AMBIGUOUS_CHRONOLOGY}public record Result(SettlementDecision decision,Reason reason,FootballFixtureEventsSnapshot.Event firstGoal){}
}
